(() => {
  'use strict';

  const SUPABASE_URL = 'https://ahslifnthiwfkmaswjno.supabase.co';
  const SUPABASE_KEY = 'sb_publishable_M4UtzEbCLwMCd9LanFWw5g_5b7-fWda';
  const FN = {
    account: `${SUPABASE_URL}/functions/v1/account-admin`,
    operations: `${SUPABASE_URL}/functions/v1/operations-v4`,
    warehouse: `${SUPABASE_URL}/functions/v1/warehouse-receiving`,
    hub: `${SUPABASE_URL}/functions/v1/staff-ops-hub`,
  };
  const ROLES = ['admin','super_admin','accountant','finance','warehouse','warehouse_china','warehouse_uae','warehouse_erbil','operations','driver','delivery'];
  const BRANCHES = ['all','china','dubai','erbil','usa'];
  const MODES = ['air','land','sea'];
  const STATUS = ['received_origin','in_transit','at_transit_hub','customs','out_for_delivery','delivered','on_hold','cancelled'];
  const state = {
    client: null,
    session: null,
    staff: null,
    tab: 'overview',
    data: { shipments: [], customers: [], staff: [], alerts: [], pricing: null, finance: null, receipts: [], logs: [], quoteRequests: [], notifications: [], staffChat: null, customerChat: null, tasks: [] },
    search: '',
    shipmentMode: 'all',
    shipmentStatus: 'all',
    activeStaffRoom: null,
    activeCustomerThread: null,
    scanStream: null,
  };

  const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money = (v, c = 'USD') => `${Number(v || 0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})} ${c}`;
  const number = (v) => Number(v || 0).toLocaleString('en-US');
  const date = (v) => v ? new Date(v).toLocaleString('ku-IQ',{dateStyle:'medium',timeStyle:'short'}) : '—';
  const shortDate = (v) => v ? new Date(v).toLocaleDateString('ku-IQ') : '—';
  const text = (v) => String(v ?? '').trim();
  const safeJson = (v) => { try { return JSON.parse(v); } catch { return v; } };
  const statusLabel = (v) => ({received_origin:'لە بنکە وەرگیراوە',in_transit:'لە ڕێگایە',at_transit_hub:'لە هەڵگرتنی ناوەندییە',customs:'گومرک',out_for_delivery:'بۆ گەیاندن',delivered:'گەیشتووە',on_hold:'وەستێنراوە',cancelled:'هەڵوەشێنراوە'})[v] || v || '—';
  const modeLabel = (v) => ({air:'ئاسمانی',land:'وشکانی',sea:'دەریایی'})[v] || v || '—';
  const roleLabel = (v) => ({super_admin:'Super Admin',admin:'Admin',accountant:'Accountant',finance:'Finance',warehouse:'Warehouse',warehouse_china:'China Warehouse',warehouse_uae:'Dubai Warehouse',warehouse_erbil:'Erbil Warehouse',operations:'Operations',driver:'Driver',delivery:'Delivery'})[v] || v || '—';
  const kindLabel = (v) => ({price:'پرسیاری نرخ',create_account:'داوای ئەکاونت',track:'پرسیاری Tracking',other:'داواکاری'})[v] || v || '—';

  function toast(message, kind='ok') {
    let el = document.getElementById('gcToast');
    if (!el) { el = document.createElement('div'); el.id = 'gcToast'; el.className = 'toast'; document.body.appendChild(el); }
    el.textContent = message;
    el.dataset.kind = kind;
    clearTimeout(el._timer);
    el._timer = setTimeout(() => el.remove(), 3400);
  }

  async function waitForSupabase() {
    const start = Date.now();
    while (!window.supabase?.createClient && Date.now() - start < 12000) await new Promise(r => setTimeout(r, 60));
    if (!window.supabase?.createClient) throw new Error('Supabase client بەردەست نییە');
    state.client = window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY, { auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true } });
    window.gcSupabase = state.client;
    window.sb = state.client;
    return state.client;
  }

  async function request(base, path='/', options={}) {
    const { data } = await state.client.auth.getSession();
    state.session = data?.session || state.session;
    if (!state.session?.access_token) throw new Error('Session ـی کارپێکردن نییە');
    const headers = { Authorization: `Bearer ${state.session.access_token}`, apikey: SUPABASE_KEY, ...(options.headers || {}) };
    const response = await fetch(base + path, { ...options, headers, cache: 'no-store' });
    const raw = await response.text();
    let payload = {};
    try { payload = raw ? JSON.parse(raw) : {}; } catch { payload = { error: raw }; }
    if (!response.ok) throw new Error(payload.error || payload.message || `HTTP ${response.status}`);
    return payload;
  }
  const account = (kind, action, data) => {
    if (action) return request(FN.account, '/', { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({kind,action,data:data||{}}) });
    return request(FN.account, `/?kind=${encodeURIComponent(kind)}`);
  };
  const ops = (kind, qs='') => request(FN.operations, `/?kind=${encodeURIComponent(kind)}${qs ? `&${qs}` : ''}`);
  const opsPost = (action, data) => request(FN.operations, '/', { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({action,data:data||{}}) });
  const hubPost = (action, data) => request(FN.hub, '/', { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({action,data:data||{}}) });

  async function identify(session) {
    const row = await account('staff');
    const me = (row.items || []).find(x => String(x.id) === String(session.user.id));
    if (!me?.is_active) throw new Error('ئەم هەژمارەیە دەستڕاگەیشتنی Staff OS نییە');
    state.staff = me;
    window.gcStaffIdentity = { id:me.id, email:session.user.email || '', role:me.role, branch:me.branch || 'all', fullName:me.full_name || '' };
  }

  async function handleLogin(email, password) {
    const { data, error } = await state.client.auth.signInWithPassword({ email, password });
    if (error) throw error;
    state.session = data.session;
    await identify(state.session);
    const aal = await state.client.auth.mfa.getAuthenticatorAssuranceLevel().catch(() => ({ data:null }));
    if (aal.data?.nextLevel === 'aal2' && aal.data.currentLevel !== 'aal2') {
      renderLogin(true);
      throw Object.assign(new Error('MFA_REQUIRED'), { code:'MFA_REQUIRED' });
    }
    renderApp();
    await loadTab('overview');
  }

  async function verifyStoredSession() {
    const { data, error } = await state.client.auth.getSession();
    if (error) throw error;
    if (!data?.session) return false;
    try { await identify(data.session); } catch { await state.client.auth.signOut(); return false; }
    const aal = await state.client.auth.mfa.getAuthenticatorAssuranceLevel().catch(() => ({ data:null }));
    if (aal.data?.nextLevel === 'aal2' && aal.data.currentLevel !== 'aal2') { renderLogin(true); return true; }
    renderApp();
    await loadTab('overview');
    return true;
  }

  function shellHTML() {
    const items = [
      ['overview','01','داشبۆرد',''],['shipments','02','بارەکان',''],['alerts','03','Alerts','alertsBadge'],['customers','04','کڕیاران',''],['pricing','05','نرخەکان',''],['warehouses','06','کۆگاکان',''],['finance','07','دارایی',''],['staff-chat','08','چاتی ستاف','staffChatBadge'],['customer-chat','09','چاتی کڕیار','customerChatBadge'],['requests','10','ئاگاداری / داواکاری','requestBadge'],['activity','11','Audit Log',''],['settings','12','ڕێکخستنەکان','']
    ];
    return `<div class="gc-shell"><aside class="gc-side"><div class="brand"><div class="brand-row"><div class="brand-logo">GC</div><div><b>Globall Cloud</b><small>STAFF OPERATING SYSTEM · V5</small></div></div></div><nav class="nav">${items.map(([id,no,label,badge]) => `<button class="nav-btn ${state.tab===id?'active':''}" data-tab="${id}"><span class="nav-icon">${no}</span><span>${label}</span>${badge?`<em class="nav-badge ${badge==='alertsBadge'?'hidden':''}" id="${badge}">0</em>`:''}</button>`).join('')}</nav><div class="side-foot"><strong id="sideName">${esc(state.staff?.full_name || 'Staff')}</strong><span id="sideRole" class="role-pill">${esc(roleLabel(state.staff?.role))} · ${esc(state.staff?.branch || 'all')}</span><div style="margin-top:8px">Session: <span style="color:var(--mint)">SECURE</span><br>Actions: <span style="color:var(--cyan2)">AUDITED</span></div><button class="btn" id="logoutBtn" style="width:100%;margin-top:8px">چوونەدەرەوە</button></div></aside><main class="gc-main"><header class="topbar"><div class="top-title"><strong id="pageTitle">Dashboard</strong><span id="pageSub">کۆنترۆڵی یەکگرتووی عملیات و کڕیاران.</span></div><div class="top-actions"><span class="status" id="systemStatus">Supabase · Secure</span><button class="btn" id="refreshBtn">↻ نوێکردنەوە</button></div></header><section class="view" id="view"></section></main></div>`;
  }

  function renderApp() {
    document.body.innerHTML = shellHTML();
    bindShell();
  }

  function renderLogin(mfa=false, message='') {
    document.body.innerHTML = `<main class="login"><section class="login-card"><div class="login-title"><div class="brand-logo">GC</div><div><b>Globall Cloud</b><div class="eyebrow">SECURE STAFF ACCESS</div></div></div><h1>${mfa?'پشتڕاستکردنەوەی 2FA':'Staff Command Center'}</h1><p>${mfa?'کۆدی ٦ ژمارەیی Google Authenticator بنووسە.':'چوونەژوورەوە بۆ سیستەمی کارگێڕی و عملیات.'}</p><form id="loginForm" style="margin-top:16px"><div id="loginFields" class="${mfa?'hidden':''}"><div class="form-field"><label>ئیمەیل</label><input class="field" id="loginEmail" type="email" autocomplete="username" required placeholder="staff@example.com"></div><div class="form-field" style="margin-top:9px"><label>وشەی نهێنی</label><input class="field" id="loginPassword" type="password" autocomplete="current-password" required placeholder="••••••••"></div></div>${mfa?'<div class="form-field"><label>کۆدی 2FA</label><input class="field" id="mfaCode" inputmode="numeric" maxlength="6" autocomplete="one-time-code" placeholder="000000" style="text-align:center;letter-spacing:6px;font:900 20px var(--mono)"></div>':' '}<div class="login-msg" id="loginMsg">${esc(message)}</div><button class="btn primary" id="loginBtn" type="submit">${mfa?'پشتڕاستکردنەوەی 2FA':'چوونەژوورەوە'}</button></form><div style="margin-top:12px;color:#6f8da8;font-size:9px">GLOBALL CLOUD · AUTH + RLS + EDGE FUNCTIONS</div></section></main>`;
    const form = document.getElementById('loginForm');
    if (!form) return;
    form.onsubmit = async (e) => {
      e.preventDefault();
      const msg = document.getElementById('loginMsg');
      const btn = document.getElementById('loginBtn');
      msg.textContent = '';
      btn.disabled = true;
      try {
        if (mfa) {
          const code = text(document.getElementById('mfaCode')?.value);
          if (!/^\d{6}$/.test(code)) throw new Error('کۆدی ٦ ژمارەیی بنووسە');
          const factors = await state.client.auth.mfa.listFactors();
          const factor = factors.data?.totp?.find(x => x.status === 'verified');
          if (!factor) throw new Error('2FA factor نەدۆزرایەوە');
          const challenge = await state.client.auth.mfa.challenge({ factorId: factor.id });
          if (challenge.error) throw challenge.error;
          const verified = await state.client.auth.mfa.verify({ factorId: factor.id, challengeId: challenge.data.id, code });
          if (verified.error) throw verified.error;
          const { data } = await state.client.auth.getSession();
          state.session = data.session;
          await identify(state.session);
          renderApp();
          await loadTab('overview');
        } else {
          await handleLogin(text(document.getElementById('loginEmail').value), document.getElementById('loginPassword').value);
        }
      } catch (err) {
        if (err?.code !== 'MFA_REQUIRED') msg.textContent = err.message || 'Login سەرکەوتوو نەبوو';
      } finally { btn.disabled = false; }
    };
  }

  function bindShell() {
    document.querySelectorAll('[data-tab]').forEach(btn => btn.addEventListener('click', () => loadTab(btn.dataset.tab)));
    document.getElementById('logoutBtn')?.addEventListener('click', async () => { await state.client.auth.signOut(); state.session=null; state.staff=null; renderLogin(); });
    document.getElementById('refreshBtn')?.addEventListener('click', () => loadTab(state.tab, true));
    updateBadges();
  }

  async function loadTab(tab, force=false) {
    state.tab = tab;
    document.querySelectorAll('[data-tab]').forEach(x => x.classList.toggle('active', x.dataset.tab === tab));
    const titles = {overview:['داشبۆرد','وێنەی گشتی لە دۆخی عملیات و پارە'],shipments:['بارەکان','ئاسمانی · وشکانی · دەریایی · tracking · carton · cargo'],alerts:['Alerts','ئاگادارییەکانی عملیات و کار'],customers:['کڕیاران','GC code · account · balance · shipment history'],pricing:['نرخەکان','Rate catalog · FX · calculator'],warehouses:['کۆگاكان','چین · دوبەی · هەولێر · ئەمریکا'],finance:['دارایی','داهات · خەرجی · قەرز · قازانج'], 'staff-chat':['چاتی ستاف','گفتوگۆی ناوخۆیی کارمەندان'], 'customer-chat':['چاتی کڕیار','وەڵامدانەوەی کڕیاران لە GC'],requests:['ئاگاداری / داواکاری','پرسیاری نرخ · account · support'],activity:['Audit Log','کێ چی کرد و کەی'],settings:['ڕێکخستنەکان','پڕۆفایل · زمان · وشەی نهێنی']};
    document.getElementById('pageTitle').textContent = titles[tab]?.[0] || tab;
    document.getElementById('pageSub').textContent = titles[tab]?.[1] || '';
    const view = document.getElementById('view');
    view.innerHTML = `<div class="empty">لە بارکردنی ${esc(titles[tab]?.[0] || tab)}…</div>`;
    try {
      if (tab==='overview') await loadOverview(force);
      else if (tab==='shipments') await renderShipments();
      else if (tab==='alerts') await renderAlerts();
      else if (tab==='customers') await renderCustomers();
      else if (tab==='pricing') await renderPricing();
      else if (tab==='warehouses') await renderWarehouses();
      else if (tab==='finance') await renderFinance();
      else if (tab==='staff-chat') await renderStaffChat();
      else if (tab==='customer-chat') await renderCustomerChat();
      else if (tab==='requests') await renderRequests();
      else if (tab==='activity') await renderActivity();
      else if (tab==='settings') await renderSettings();
      document.getElementById('systemStatus').textContent = 'Supabase · Live';
    } catch (err) {
      view.innerHTML = `<div class="empty"><strong style="color:var(--red)">هەڵەی module</strong><div style="margin-top:5px">${esc(err.message)}</div><button class="btn" data-retry style="margin-top:10px">↻ دووبارە هەوڵدان</button></div>`;
      view.querySelector('[data-retry]')?.addEventListener('click', () => loadTab(tab, true));
      document.getElementById('systemStatus').textContent = 'Supabase · Error';
    }
    updateBadges();
  }

  async function loadOverview() {
    const results = await Promise.allSettled([ops('shipments'), ops('customers'), ops('finance'), ops('alerts'), account('notification'), account('quote_requests'), account('task'), account('log'), ops('pricing')]);
    const val = (i, fallback) => results[i].status === 'fulfilled' ? results[i].value : fallback;
    state.data.shipments = val(0,{items:[]}).items || [];
    state.data.customers = val(1,{items:[]}).items || [];
    state.data.finance = val(2,{transactions:[],summary:[]});
    state.data.alerts = val(3,{items:[]}).items || [];
    state.data.notifications = val(4,{items:[]}).items || [];
    state.data.quoteRequests = val(5,{items:[]}).items || [];
    state.data.tasks = val(6,{items:[]}).items || [];
    state.data.logs = val(7,{items:[]}).items || [];
    state.data.pricing = val(8,{rates:[],exchange_rates:[],rules:[]});
    const tx = state.data.finance.transactions || [];
    const income = tx.filter(x=>['income','customer_payment','payment'].includes(String(x.type))).reduce((s,x)=>s+Number(x.amount_usd||0),0);
    const expense = tx.filter(x=>['expense','cost'].includes(String(x.type))).reduce((s,x)=>s+Number(x.amount_usd||0),0);
    const due = tx.filter(x=>['charge','customer_charge'].includes(String(x.type))).reduce((s,x)=>s+Number(x.amount_usd||0),0);
    const paid = tx.filter(x=>['payment','customer_payment','income'].includes(String(x.type))).reduce((s,x)=>s+Number(x.amount_usd||0),0);
    const openAlerts = state.data.alerts.filter(x => Array.isArray(x.read_by) ? !x.read_by.includes(state.staff.id) : !x.read_at).length;
    const activeShipments = state.data.shipments.filter(x=>!['delivered','cancelled'].includes(x.status)).length;
    const routes = new Map();
    for (const s of state.data.shipments) { const key=`${s.origin_key||'—'} → ${s.dest_key||'—'}`; routes.set(key,(routes.get(key)||0)+Number(s.total_amount||0)); }
    const topRoutes = [...routes.entries()].sort((a,b)=>b[1]-a[1]).slice(0,6);
    const tasksOpen = state.data.tasks.filter(t=>!['done','cancelled'].includes(t.status)).length;
    document.getElementById('view').innerHTML = `<div class="section-head"><div><div class="eyebrow">GLOBAL CLOUD · CONTROL TOWER</div><h1>داشبۆردی زیرەک</h1><p>هەموو ڕووداوەکانی بار، کڕیار، دارایی و ستاف لە یەک شوێن.</p></div><div class="actions"><button class="btn primary" data-jump="shipments">+ بار</button><button class="btn" data-jump="customers">+ کڕیار</button><button class="btn" data-jump="warehouses">+ وەرگرتن لە کۆگا</button></div></div><div class="grid-kpi"><div class="kpi"><span>هەموو بار</span><strong>${number(state.data.shipments.length)}</strong><small>records</small></div><div class="kpi"><span>بارە چالاکەکان</span><strong>${number(activeShipments)}</strong><small>in operation</small></div><div class="kpi"><span>کڕیار</span><strong>${number(state.data.customers.length)}</strong><small>GC accounts</small></div><div class="kpi"><span>قازانجی خام</span><strong>${money(income-expense)}</strong><small>USD</small></div><div class="kpi"><span>قەرز / ماوە</span><strong>${money(Math.max(0,due-paid))}</strong><small>USD</small></div><div class="kpi"><span>ئاگاداری نوێ</span><strong>${number(openAlerts)}</strong><small>unread</small></div></div><div class="two-col"><section class="card"><div class="card-head"><h3>ڕێڕەوە سەرەکییەکان</h3><span class="pill">Revenue view</span></div><div class="list">${topRoutes.length?topRoutes.map(([route,v])=>`<div class="mini-row"><div><b>${esc(route)}</b><span style="display:block;margin-top:3px">کۆی بڕی بار</span></div><strong class="mono">${money(v)}</strong></div>`).join(''):'<div class="empty">داتا نییە.</div>'}</div></section><section class="card"><div class="card-head"><h3>Attention Center</h3><button class="btn" data-jump="alerts">بینین</button></div><div class="list">${state.data.alerts.slice(0,6).map(a=>`<div class="notice ${a.read_by?.includes(state.staff.id)?'':'unread'}"><div><b>${esc(a.title||'Alert')}</b><p>${esc(a.body||a.message||'')}</p></div><time>${esc(shortDate(a.created_at))}</time></div>`).join('')||'<div class="empty">هیچ ئاگادارییەکی نوێ نییە.</div>'}</div></section></div><div class="three-col" style="margin-top:10px"><section class="card"><div class="card-head"><h3>چالاکییە نوێکان</h3><button class="btn" data-jump="activity">Audit</button></div><div class="list">${state.data.logs.slice(0,7).map(l=>`<div class="mini-row"><div><b>${esc(l.action)}</b><span>${esc(l.staff_name||'Staff')} · ${esc(shortDate(l.created_at))}</span></div><span class="mono">${esc(l.target_id||'')}</span></div>`).join('')||'<div class="empty">هیچ record ـێک نییە.</div>'}</div></section><section class="card"><div class="card-head"><h3>Task Queue</h3><span class="pill warn">${tasksOpen} open</span></div><div class="list">${state.data.tasks.slice(0,6).map(t=>`<div class="mini-row"><div><b>${esc(t.title)}</b><span>${esc(t.assignee?.full_name||'بێ دیاریکردن')}</span></div><span class="pill">${esc(t.status)}</span></div>`).join('')||'<div class="empty">Task نییە.</div>'}</div></section><section class="card"><div class="card-head"><h3>FX</h3><span class="pill mint">Live catalog</span></div>${(state.data.pricing.exchange_rates||[]).slice(0,2).map(r=>`<div class="mini-row"><div><b>${esc(r.base_currency||'USD')} → ${esc(r.quote_currency||'IQD')}</b><span>${esc(r.effective_from||'')}</span></div><strong class="mono">${esc(r.rate??r.usd_to_iqd??'—')}</strong></div>`).join('')||'<div class="empty">FX داتا نییە.</div>'}</section></div>`;
    document.querySelectorAll('[data-jump]').forEach(x=>x.addEventListener('click',()=>loadTab(x.dataset.jump)));
  }

  async function renderShipments() {
    const res = await ops('shipments'); state.data.shipments = res.items || [];
    document.getElementById('view').innerHTML = `<div class="section-head"><div><div class="eyebrow">LIVE SHIPMENT CONTROL</div><h1>بارەکان</h1><p>هەموو بارەکان: Air / Land / Sea، کۆدی GC، کارتۆن، کاڵا و بەرواری بەڕێکردن.</p></div><div class="actions"><button class="btn primary" id="newShipmentBtn">+ بارێکی نوێ</button><a class="btn" href="/track" target="_blank" rel="noopener">Public Tracking ↗</a></div></div><div class="toolbar"><input class="field" id="shipmentSearch" placeholder="گەڕان بە GC / tracking / کڕیار / route"><select class="field" id="shipmentMode"><option value="all">هەموو جۆرەکان</option>${MODES.map(m=>`<option value="${m}">${modeLabel(m)}</option>`).join('')}</select><select class="field" id="shipmentStatus"><option value="all">هەموو status ـەکان</option>${STATUS.map(s=>`<option value="${s}">${statusLabel(s)}</option>`).join('')}</select></div><div class="table-wrap"><table class="table"><thead><tr><th>GC / Tracking</th><th>کڕیار</th><th>route</th><th>جۆر</th><th>حالت</th><th>کارتۆن</th><th>کێش</th><th>بەروار</th><th></th></tr></thead><tbody id="shipmentRows"></tbody></table></div>`;
    const draw = () => { const q=text(document.getElementById('shipmentSearch')?.value).toLowerCase(); const m=document.getElementById('shipmentMode').value; const s=document.getElementById('shipmentStatus').value; const rows=state.data.shipments.filter(x=>(m==='all'||x.transport_mode===m)&&(s==='all'||x.status===s)&&(!q||JSON.stringify(x).toLowerCase().includes(q))); document.getElementById('shipmentRows').innerHTML=rows.length?rows.map(x=>`<tr><td><b class="mono">${esc(x.customer_gc_code||'—')}</b><span style="display:block;margin-top:3px;color:var(--muted)">${esc(x.tracking_id||'—')}</span></td><td>${esc(x.customer_name||'—')}<span style="display:block;color:var(--muted);font-size:9px">${esc(x.customer_phone||'')}</span></td><td>${esc(x.origin_key||x.origin_warehouse||'—')} → ${esc(x.dest_key||x.destination_warehouse||'—')}</td><td><span class="pill">${esc(modeLabel(x.transport_mode||x.type))}</span></td><td><span class="pill ${x.status==='delivered'?'mint':x.status==='cancelled'?'red':'warn'}">${esc(statusLabel(x.status))}</span></td><td>${number(x.carton_count||x.items_count)}</td><td>${x.chargeable_weight_kg??x.weight_kg??'—'} kg</td><td>${esc(shortDate(x.step_dates?.departed||x.created_at))}</td><td><div class="actions"><button class="btn small" data-view-ship="${esc(x.id)}">بینین</button><button class="btn small" data-edit-ship="${esc(x.id)}">دەستکاری</button></div></td></tr>`).join(''):`<tr><td colspan="9"><div class="empty">هیچ بارێک نەدۆزرایەوە.</div></td></tr>`; document.querySelectorAll('[data-view-ship]').forEach(b=>b.onclick=()=>shipDetail(b.dataset.viewShip)); document.querySelectorAll('[data-edit-ship]').forEach(b=>b.onclick=()=>editShipment(b.dataset.editShip)); };
    ['shipmentSearch','shipmentMode','shipmentStatus'].forEach(id=>document.getElementById(id).addEventListener('input',draw)); draw(); document.getElementById('newShipmentBtn').onclick=()=>newShipmentModal();
  }

  async function shipDetail(id) { const d=await ops('shipment',`id=${encodeURIComponent(id)}`); const s=d.shipment||{}; const ev=d.events||[]; const receipts=d.receipts||[]; const photos=receipts.flatMap(r=>Array.isArray(r.photos)?r.photos:[]); openModal(`بار · ${s.customer_gc_code||s.tracking_id||''}`,`<div class="two-col"><section class="card"><div class="card-head"><h3>کڕیار و مسیر</h3><span class="pill">${esc(modeLabel(s.transport_mode||s.type))}</span></div><p><b>${esc(s.customer_name||'—')}</b> · ${esc(s.customer_gc_code||'—')}</p><p class="muted">${esc(s.origin_warehouse||s.origin_key||'—')} → ${esc(s.destination_warehouse||s.dest_key||'—')}</p><p class="muted">بەرێکراو: ${esc(date(s.step_dates?.departed||s.created_at))}</p><p class="muted">ETA: ${esc(date(s.eta))}</p></section><section class="card"><div class="card-head"><h3>حیساب</h3><span class="pill mint">${money(s.total_amount||0,s.currency||'USD')}</span></div><p>Actual: <b>${esc(s.actual_weight_kg??s.weight_kg??'—')} kg</b></p><p>Volumetric: <b>${esc(s.volumetric_weight_kg??'—')} kg</b></p><p>Chargeable: <b>${esc(s.chargeable_weight_kg??'—')} kg</b></p><p>Cartons: <b>${esc(s.carton_count??s.items_count??'—')}</b></p></section><section class="card"><div class="card-head"><h3>کاڵا</h3></div><p class="muted">${esc(s.cargo_description||s.description||'تێبینییەک نییە.')}</p></section><section class="card"><div class="card-head"><h3>Status</h3></div><p><span class="pill warn">${esc(statusLabel(s.status))}</span></p></section><section class="card" style="grid-column:1/-1"><div class="card-head"><h3>Timeline</h3></div><div class="timeline">${ev.length?ev.map(e=>`<div class="timeline-row"><time>${esc(date(e.created_at||e.occurred_at))}</time><div><b>${esc(statusLabel(e.status)||e.event_type||'Event')}</b><span>${esc(e.location||e.location_label||e.note||'')}</span></div></div>`).join(''):'<div class="empty">هێشتا event نییە.</div>'}</div></section>${photos.length?`<section class="card" style="grid-column:1/-1"><div class="card-head"><h3>وێنەکانی کۆگا</h3></div><div class="photo-grid">${photos.slice(0,12).map(u=>`<a class="photo" href="${esc(u)}" target="_blank" rel="noopener"><img src="${esc(u)}" alt="Warehouse evidence"></a>`).join('')}</div></section>`:''}</div>`,'<button class="btn" data-close>داخستن</button>'); }

  function newShipmentModal() { openModal('دروستکردنی بار',`<form id="shipForm" class="form-grid"><div class="form-field"><label>GC code</label><input class="field" name="customer_gc_code" required placeholder="GC-1005"></div><div class="form-field"><label>Tracking</label><input class="field" name="tracking_id" required placeholder="GC-2026-0001"></div><div class="form-field"><label>Mode</label><select class="field" name="transport_mode">${MODES.map(x=>`<option value="${x}">${modeLabel(x)}</option>`).join('')}</select></div><div class="form-field"><label>Cartons</label><input class="field" name="carton_count" type="number" min="1" value="1"></div><div class="form-field"><label>Origin warehouse</label><input class="field" name="origin_warehouse" placeholder="China"></div><div class="form-field"><label>Destination warehouse</label><input class="field" name="destination_warehouse" value="Erbil"></div><div class="form-field"><label>Actual kg</label><input class="field" name="actual_weight_kg" type="number" step="0.01"></div><div class="form-field"><label>Length cm</label><input class="field" name="length_cm" type="number" step="0.01"></div><div class="form-field"><label>Width cm</label><input class="field" name="width_cm" type="number" step="0.01"></div><div class="form-field"><label>Height cm</label><input class="field" name="height_cm" type="number" step="0.01"></div><div class="form-field full"><label>کاڵا</label><textarea class="field" name="cargo_description" placeholder="2 laptop, 5 cover..."></textarea></div></form>`,'<button class="btn" data-close>هەڵوەشاندنەوە</button><button class="btn primary" id="saveShip">دروستکردن</button>'); document.getElementById('saveShip').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('shipForm')).entries()); try{const r=await opsPost('shipment_update',{...d,id:d.tracking_id,status:'received_origin'}); closeModal(); toast('بارەکە تۆمار کرا'); await renderShipments(); return r;}catch(e){toast(e.message,'bad')}}; }

  async function editShipment(id) { const d=await ops('shipment',`id=${encodeURIComponent(id)}`); const s=d.shipment||{}; openModal(`دەستکاری · ${s.customer_gc_code||s.tracking_id||''}`,`<form id="shipEdit" class="form-grid"><input type="hidden" name="id" value="${esc(s.id)}"><div class="form-field"><label>Status</label><select class="field" name="status">${STATUS.map(x=>`<option value="${x}" ${x===s.status?'selected':''}>${statusLabel(x)}</option>`).join('')}</select></div><div class="form-field"><label>Mode</label><select class="field" name="transport_mode">${MODES.map(x=>`<option value="${x}" ${x===s.transport_mode?'selected':''}>${modeLabel(x)}</option>`).join('')}</select></div><div class="form-field"><label>Origin warehouse</label><input class="field" name="origin_warehouse" value="${esc(s.origin_warehouse||s.origin_key||'')}"></div><div class="form-field"><label>Destination warehouse</label><input class="field" name="destination_warehouse" value="${esc(s.destination_warehouse||s.dest_key||'Erbil')}"></div><div class="form-field"><label>Cartons</label><input class="field" name="carton_count" type="number" min="0" value="${esc(s.carton_count||0)}"></div><div class="form-field"><label>Actual kg</label><input class="field" name="actual_weight_kg" type="number" step="0.01" value="${esc(s.actual_weight_kg??s.weight_kg??'')}"></div><div class="form-field"><label>Length</label><input class="field" name="length_cm" type="number" step="0.01" value="${esc(s.length_cm??'')}"></div><div class="form-field"><label>Width</label><input class="field" name="width_cm" type="number" step="0.01" value="${esc(s.width_cm??'')}"></div><div class="form-field"><label>Height</label><input class="field" name="height_cm" type="number" step="0.01" value="${esc(s.height_cm??'')}"></div><div class="form-field full"><label>کاڵا</label><textarea class="field" name="cargo_description">${esc(s.cargo_description||'')}</textarea></div></form>`,'<button class="btn" data-close>هەڵوەشاندنەوە</button><button class="btn primary" id="saveShipEdit">پاشەکەوت</button>'); document.getElementById('saveShipEdit').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('shipEdit')).entries()); try{await opsPost('shipment_update',d);closeModal();toast('نوێکراوەتەوە');await renderShipments()}catch(e){toast(e.message,'bad')}}; }

  async function renderAlerts() { const r=await ops('alerts'); state.data.alerts=r.items||[]; const unread=state.data.alerts.filter(x=>!Array.isArray(x.read_by)||!x.read_by.includes(state.staff.id)).length; document.getElementById('view').innerHTML=`<div class="section-head"><div><div class="eyebrow">ALERT CENTER</div><h1>Alerts</h1><p>${number(unread)} ئاگادارییەکی ناخوێندراوە.</p></div></div><div class="list" id="alertList">${state.data.alerts.length?state.data.alerts.map(a=>`<article class="notice ${Array.isArray(a.read_by)&&a.read_by.includes(state.staff.id)?'':'unread'}"><div><b>${esc(a.title||a.kind||'Alert')}</b><p>${esc(a.body||a.message||'')}</p><small>${esc(date(a.created_at))}</small></div><button class="btn" data-alert-read="${esc(a.id)}">${Array.isArray(a.read_by)&&a.read_by.includes(state.staff.id)?'خوێندراوە':'خوێندنەوە'}</button></article>`).join(''):'<div class="empty">هیچ ئاگادارییەک نییە.</div>'}</div><section class="card" style="margin-top:10px"><div class="card-head"><h3>دروستکردنی Alert</h3></div><form id="alertForm" class="form-grid"><div class="form-field"><label>جۆر</label><input class="field" name="kind" value="operations"></div><div class="form-field"><label>Severity</label><select class="field" name="severity"><option>normal</option><option>high</option><option>critical</option></select></div><div class="form-field full"><label>ناونیشان</label><input class="field" name="title" required></div><div class="form-field full"><label>پەیام</label><textarea class="field" name="body"></textarea></div></form><button class="btn primary" id="createAlert" style="margin-top:9px">دروستکردنی Alert</button></section>`; document.querySelectorAll('[data-alert-read]').forEach(b=>b.onclick=async()=>{try{await opsPost('alert_read',{id:b.dataset.alertRead});await renderAlerts()}catch(e){toast(e.message,'bad')}});document.getElementById('createAlert').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('alertForm')).entries());try{await opsPost('alert_create',d);toast('Alert دروست کرا');await renderAlerts()}catch(e){toast(e.message,'bad')}}; }

  async function renderCustomers() { const r=await ops('customers'); state.data.customers=r.items||[]; document.getElementById('view').innerHTML=`<div class="section-head"><div><div class="eyebrow">CUSTOMER 360</div><h1>کڕیاران</h1><p>هەموو GC account ـەکان، balance، shipment و مدیریت.</p></div><div class="actions"><button class="btn primary" id="newCustomer">+ کڕیاری نوێ</button><button class="btn" id="customerScanner">⌁ Scan GC</button></div></div><div class="toolbar"><input class="field" id="customerSearch" placeholder="گەڕان بە GC / ناو / ژمارە / شار"></div><div class="table-wrap"><table class="table"><thead><tr><th>GC</th><th>ناو</th><th>پەیوەندی</th><th>shipment</th><th>ماوە</th><th>manager</th><th>حالت</th><th></th></tr></thead><tbody id="customerRows"></tbody></table></div>`; const draw=()=>{const q=text(document.getElementById('customerSearch').value).toLowerCase();const rows=state.data.customers.filter(x=>!q||`${x.gc_code||x.code} ${x.name} ${x.phone} ${x.city}`.toLowerCase().includes(q));document.getElementById('customerRows').innerHTML=rows.map(x=>`<tr><td class="mono"><b>${esc(x.gc_code||x.code||'—')}</b></td><td><b>${esc(x.name||'—')}</b><span style="display:block;color:var(--muted);font-size:9px">${esc(x.email||'')}</span></td><td>${esc(x.phone||'—')}</td><td>${number(x.shipment_count)}</td><td>${money(x.outstanding_amount||0)}</td><td>${esc(x.manager_staff_id||'—')}</td><td><span class="pill ${x.is_active===false?'red':'mint'}">${x.is_active===false?'ناچالاک':'چالاک'}</span></td><td><div class="actions"><button class="btn" data-customer="${esc(x.id)}">بینین</button><button class="btn" data-customer-edit="${esc(x.id)}">دەستکاری</button><button class="btn" data-customer-code="${esc(x.id)}">QR</button></div></td></tr>`).join('')||`<tr><td colspan="8"><div class="empty">هیچ کڕیارێک نییە.</div></td></tr>`;document.querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>customerDetail(b.dataset.customer));document.querySelectorAll('[data-customer-edit]').forEach(b=>b.onclick=()=>editCustomer(b.dataset.customer));document.querySelectorAll('[data-customer-code]').forEach(b=>b.onclick=()=>customerCode(b.dataset.customer));}; document.getElementById('customerSearch').oninput=draw; draw(); document.getElementById('newCustomer').onclick=newCustomerModal; document.getElementById('customerScanner').onclick=()=>scannerModal('customer'); }

  async function customerDetail(id) { const c=state.data.customers.find(x=>String(x.id)===String(id)); if(!c)return; const ship=(state.data.shipments||[]).filter(x=>String(x.directory_customer_id||x.customer_id||'')===String(c.id)||String(x.customer_gc_code||'')===String(c.gc_code||c.code||'')); openModal(`${c.gc_code||c.code||''} · ${c.name||''}`,`<div class="two-col"><section class="card"><h3>Identity</h3><p>GC: <b class="mono">${esc(c.gc_code||c.code)}</b></p><p>ناو: <b>${esc(c.name)}</b></p><p>Phone: ${esc(c.phone||'—')}</p><p>Email: ${esc(c.email||'—')}</p><p>شار: ${esc(c.city||'—')}</p></section><section class="card"><h3>Account</h3><p>Shipments: <b>${number(c.shipment_count)}</b></p><p>Outstanding: <b>${money(c.outstanding_amount||0)}</b></p><p>Status: <span class="pill ${c.is_active?'mint':'red'}">${c.is_active?'ACTIVE':'INACTIVE'}</span></p><p>Created: ${esc(date(c.created_at))}</p></section><section class="card" style="grid-column:1/-1"><div class="card-head"><h3>بارەکان</h3><span class="pill">${ship.length}</span></div><div class="list">${ship.slice(0,12).map(s=>`<div class="mini-row"><div><b>${esc(s.tracking_id||'—')}</b><span>${esc(modeLabel(s.transport_mode))} · ${esc(statusLabel(s.status))}</span></div><strong class="mono">${money(s.total_amount||0)}</strong></div>`).join('')||'<div class="empty">هێشتا shipment ـێک نییە.</div>'}</div></section></div>`,'<button class="btn" id="customerQRBtn">QR / Barcode</button><button class="btn" data-close>داخستن</button>'); document.getElementById('customerQRBtn').onclick=()=>{closeModal();customerCode(id)}; }

  function newCustomerModal() { openModal('دروستکردنی کڕیار + GC Account',`<form id="customerForm" class="form-grid"><div class="form-field"><label>GC code (optional)</label><input class="field" name="gc_code" placeholder="GC-1088"></div><div class="form-field"><label>ناوی کڕیار</label><input class="field" name="name" required></div><div class="form-field"><label>Phone</label><input class="field" name="phone"></div><div class="form-field"><label>Email</label><input class="field" name="email" type="email"></div><div class="form-field"><label>City</label><input class="field" name="city" value="Erbil"></div><div class="form-field"><label>Delivery location</label><input class="field" name="delivery_location"></div><div class="form-field"><label>Password (optional)</label><input class="field" name="password" type="text"></div><div class="form-field"><label>Send invite</label><select class="field" name="send_invite"><option value="false">No</option><option value="true">Yes — email invite</option></select></div><div class="form-field full"><label>Note</label><textarea class="field" name="note"></textarea></div></form>`,'<button class="btn" data-close>هەڵوەشاندنەوە</button><button class="btn primary" id="saveCustomer">دروستکردن</button>'); document.getElementById('saveCustomer').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('customerForm')).entries());d.send_invite=d.send_invite==='true';try{const r=await opsPost('customer_create',d);closeModal();toast(`کڕیار ${r.customer?.gc_code||r.customer?.code||''} دروست کرا`);if(r.temporary_password)toast(`Temporary password: ${r.temporary_password}`);await renderCustomers()}catch(e){toast(e.message,'bad')}}; }

  function editCustomer(id) { const c=state.data.customers.find(x=>String(x.id)===String(id));if(!c)return;openModal(`دەستکاری کڕیار · ${c.gc_code||c.code}`,`<form id="editCustomer" class="form-grid"><input type="hidden" name="id" value="${esc(c.id)}"><div class="form-field"><label>GC code</label><input class="field" value="${esc(c.gc_code||c.code||'')}" disabled></div><div class="form-field"><label>ناو</label><input class="field" name="name" value="${esc(c.name||'')}"></div><div class="form-field"><label>Phone</label><input class="field" name="phone" value="${esc(c.phone||'')}"></div><div class="form-field"><label>Email</label><input class="field" name="email" type="email" value="${esc(c.email||'')}"></div><div class="form-field"><label>City</label><input class="field" name="city" value="${esc(c.city||'')}"></div><div class="form-field"><label>Delivery</label><input class="field" name="delivery_location" value="${esc(c.delivery_location||'')}"></div><div class="form-field"><label>Active</label><select class="field" name="is_active"><option value="true" ${c.is_active?'selected':''}>Active</option><option value="false" ${!c.is_active?'selected':''}>Inactive</option></select></div><div class="form-field"><label>New password (optional)</label><input class="field" name="password" type="text"></div><div class="form-field full"><label>Note</label><textarea class="field" name="note">${esc(c.note||'')}</textarea></div></form>`,'<button class="btn danger" id="archiveCustomer">Deactivate</button><button class="btn" data-close>هەڵوەشاندنەوە</button><button class="btn primary" id="saveCustomerEdit">پاشەکەوت</button>');document.getElementById('saveCustomerEdit').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('editCustomer')).entries());d.is_active=d.is_active==='true';try{await account('customer','update',d);closeModal();toast('کڕیار نوێکرایەوە');await renderCustomers()}catch(e){toast(e.message,'bad')}};document.getElementById('archiveCustomer').onclick=async()=>{try{await account('customer','delete',{id:c.id});closeModal();toast('کڕیار ناچالاک کرا');await renderCustomers()}catch(e){toast(e.message,'bad')}}; }

  async function customerCode(id) { const c=state.data.customers.find(x=>String(x.id)===String(id));if(!c)return;const code=c.gc_code||c.code;openModal(`GC Identity · ${code}`,`<div class="qr-wrap"><div><div class="code-box"><canvas id="gcQr" width="220" height="220"></canvas></div></div><div><div class="barcode-box"><svg id="gcBarcode"></svg></div><p class="muted" style="margin-top:10px;text-align:center">${esc(c.name||'')} · ${esc(c.phone||'')}</p></div></div>`,'<button class="btn" id="printCode">چاپ</button><button class="btn" data-close>داخستن</button>'); try{if(window.QRCode)await window.QRCode.toCanvas(document.getElementById('gcQr'),`${location.origin}/track?gc=${encodeURIComponent(code)}`,{width:220,margin:2});if(window.JsBarcode)window.JsBarcode('#gcBarcode',code,{format:'CODE128',width:2,height:64,displayValue:true});}catch(e){toast(e.message,'bad')}document.getElementById('printCode').onclick=()=>window.print(); }

  async function renderPricing() { const r=await ops('pricing');state.data.pricing=r;const rates=r.rates||[];const fx=r.exchange_rates||[];document.getElementById('view').innerHTML=`<div class="section-head"><div><div class="eyebrow">PRICING ENGINE</div><h1>نرخەکان</h1><p>هەموو نرخەکان editable ـن و FX تاریخچەی هەیە.</p></div><div class="actions"><button class="btn primary" id="newRate">+ نرخێکی نوێ</button><button class="btn" id="newFx">+ نرخەی USD/IQD</button></div></div><div class="three-col"><section class="card"><div class="card-head"><h3>China Air</h3><span class="pill">kg</span></div>${rates.filter(x=>String(x.origin_key).toLowerCase().includes('china')&&x.transport_mode==='air').map(rateRow).join('')||'<div class="empty">داتا نییە.</div>'}</section><section class="card"><div class="card-head"><h3>UAE Air / Land</h3><span class="pill">route</span></div>${rates.filter(x=>String(x.origin_key).toLowerCase().includes('uae')||String(x.origin_key).toLowerCase().includes('dubai')).map(rateRow).join('')||'<div class="empty">داتا نییە.</div>'}</section><section class="card"><div class="card-head"><h3>هەموو نرخەکان</h3><span class="pill mint">${rates.length}</span></div>${rates.slice(0,15).map(rateRow).join('')||'<div class="empty">داتا نییە.</div>'}</section></div><section class="card" style="margin-top:10px"><div class="card-head"><h3>USD / IQD</h3><span class="pill warn">History</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Rate</th><th>Source</th><th>Effective</th><th>Updated</th></tr></thead><tbody>${fx.slice(0,20).map(x=>`<tr><td class="mono"><b>${esc(x.rate??x.usd_to_iqd??'—')}</b></td><td>${esc(x.source_note||x.source||'manual')}</td><td>${esc(x.effective_from||x.effective_on||'')}</td><td>${esc(date(x.updated_at||x.created_at))}</td></tr>`).join('')||'<tr><td colspan="4"><div class="empty">هیچ FX history نییە.</div></td></tr>'}</tbody></table></div></section><section class="card" style="margin-top:10px"><div class="card-head"><h3>Calculator</h3><span class="pill">Volumetric / 6000</span></div><form id="calcForm" class="form-grid"><div class="form-field"><label>Mode</label><select class="field" name="transport_mode"><option value="air">Air</option><option value="sea">Sea</option><option value="land">Land</option></select></div><div class="form-field"><label>Rate / unit</label><input class="field" name="rate" type="number" step="0.01" value="9"></div><div class="form-field"><label>Actual kg</label><input class="field" name="actual_weight" type="number" step="0.01"></div><div class="form-field"><label>L cm</label><input class="field" name="length_cm" type="number" step="0.01"></div><div class="form-field"><label>W cm</label><input class="field" name="width_cm" type="number" step="0.01"></div><div class="form-field"><label>H cm</label><input class="field" name="height_cm" type="number" step="0.01"></div></form><div id="calcResult" class="kpi" style="margin-top:10px"><span>حیساب</span><strong>0.00</strong><small>USD</small></div><button class="btn primary" id="runCalc" style="margin-top:8px">حیساب بکە</button></section>`; document.querySelectorAll('[data-edit-rate]').forEach(b=>b.onclick=()=>editRate(b.dataset.editRate));document.getElementById('newRate').onclick=newRateModal;document.getElementById('newFx').onclick=newFxModal;document.getElementById('runCalc').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('calcForm')).entries());try{const r=await opsPost('quote_calculate',{...d,origin_key:'china',destination_key:'erbil',product_type:'General goods / no battery / no screen'});document.querySelector('#calcResult strong').textContent=money(r.total,r.currency)}catch(e){const actual=Number(d.actual_weight||0),v=(Number(d.length_cm||0)*Number(d.width_cm||0)*Number(d.height_cm||0))/6000,b=Math.max(actual,v),total=b*Number(d.rate||0);document.querySelector('#calcResult strong').textContent=money(total)}} }
  function rateRow(x){return `<div class="mini-row"><div><b>${esc(x.product_type||x.name_ku||'Rate')}</b><span>${esc(x.origin_key||'')} → ${esc(x.destination_key||'')} · ${esc(x.transit_min_days??'—')}-${esc(x.transit_max_days??'—')} days</span></div><div style="text-align:end"><strong class="mono">${esc(x.amount??x.price_usd??'—')} ${esc(x.currency||'USD')}</strong><button class="btn" data-edit-rate="${esc(x.id)}" style="display:block;margin-top:5px">دەستکاری</button></div></div>` }
  function newRateModal(){openModal('زیادکردنی نرخ',`<form id="rateForm" class="form-grid"><div class="form-field"><label>Origin</label><input class="field" name="origin_key" placeholder="china"></div><div class="form-field"><label>Destination</label><input class="field" name="destination_key" value="erbil"></div><div class="form-field"><label>Mode</label><select class="field" name="transport_mode">${MODES.map(x=>`<option value="${x}">${modeLabel(x)}</option>`).join('')}</select></div><div class="form-field"><label>Product type</label><input class="field" name="product_type" required></div><div class="form-field"><label>Amount</label><input class="field" name="amount" type="number" step="0.01" min="0" required></div><div class="form-field"><label>Unit</label><select class="field" name="unit"><option value="kg">kg</option><option value="cbm">cbm</option></select></div><div class="form-field"><label>Min days</label><input class="field" name="transit_min_days" type="number"></div><div class="form-field"><label>Max days</label><input class="field" name="transit_max_days" type="number"></div><div class="form-field full"><label>Notes</label><textarea class="field" name="notes"></textarea></div></form>`,'<button class="btn" data-close>هەڵوەشاندنەوە</button><button class="btn primary" id="saveRate">دروستکردن</button>');document.getElementById('saveRate').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('rateForm')).entries());try{await hubPost('pricing_create',{...d,price_usd:d.amount});closeModal();toast('نرخ زیاد کرا');await renderPricing()}catch(e){toast(e.message,'bad')}};}
  function editRate(id){const x=(state.data.pricing.rates||[]).find(r=>String(r.id)===String(id));if(!x)return;openModal('دەستکاری نرخ',`<form id="editRate" class="form-grid"><input type="hidden" name="id" value="${esc(x.id)}"><div class="form-field"><label>Product</label><input class="field" value="${esc(x.product_type)}" disabled></div><div class="form-field"><label>Amount</label><input class="field" name="amount" type="number" step="0.01" value="${esc(x.amount??0)}"></div><div class="form-field"><label>Min days</label><input class="field" name="transit_min_days" type="number" value="${esc(x.transit_min_days??'')}"></div><div class="form-field"><label>Max days</label><input class="field" name="transit_max_days" type="number" value="${esc(x.transit_max_days??'')}"></div><div class="form-field full"><label>Notes</label><textarea class="field" name="notes">${esc(x.notes||'')}</textarea></div></form>`,'<button class="btn" data-close>هەڵوەشاندنەوە</button><button class="btn primary" id="saveEditRate">پاشەکەوت</button>');document.getElementById('saveEditRate').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('editRate')).entries());try{await opsPost('pricing_update',{...d,amount:Number(d.amount)});closeModal();toast('نرخ نوێکرایەوە');await renderPricing()}catch(e){toast(e.message,'bad')}};}
  function newFxModal(){openModal('گۆڕینی USD/IQD',`<form id="fxForm" class="form-grid"><div class="form-field"><label>USD → IQD</label><input class="field" name="usd_to_iqd" type="number" step="0.01" required placeholder="1550"></div><div class="form-field"><label>Source</label><input class="field" name="source" value="manual"></div></form>`,'<button class="btn" data-close>هەڵوەشاندنەوە</button><button class="btn primary" id="saveFx">پاشەکەوت</button>');document.getElementById('saveFx').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('fxForm')).entries());try{await opsPost('fx_update',d);closeModal();toast('FX نوێکرایەوە');await renderPricing()}catch(e){toast(e.message,'bad')}};}

  async function renderWarehouses(){const r=await request(FN.warehouse,'/');state.data.receipts=r.items||[];document.getElementById('view').innerHTML=`<div class="section-head"><div><div class="eyebrow">WAREHOUSE CHAIN OF CUSTODY</div><h1>کۆگاكان</h1><p>چین · دوبەی · هەولێر · ئەمریکا، وەرگرتنی carton و بەڵگەی وێنە.</p></div><div class="actions"><button class="btn primary" id="newReceipt">+ وەرگرتن</button><button class="btn" id="scanReceipt">⌁ Scan GC</button></div></div><div class="grid-kpi"><div class="kpi"><span>Receipts</span><strong>${number(state.data.receipts.length)}</strong></div><div class="kpi"><span>Verified</span><strong>${number(state.data.receipts.filter(x=>x.verification_status==='verified').length)}</strong></div><div class="kpi"><span>Today</span><strong>${number(state.data.receipts.filter(x=>shortDate(x.received_at)===shortDate(new Date())).length)}</strong></div><div class="kpi"><span>Photos</span><strong>${number(state.data.receipts.reduce((s,x)=>s+(Array.isArray(x.photos)?x.photos.length:0),0))}</strong></div></div><div class="toolbar"><input class="field" id="warehouseSearch" placeholder="گەڕان بە GC / batch / tracking / کۆگا"></div><div class="table-wrap"><table class="table"><thead><tr><th>GC</th><th>کۆگا</th><th>Batch</th><th>Cartons</th><th>Tracking</th><th>وەرگر</th><th>وێنە</th><th>بەروار</th><th></th></tr></thead><tbody id="warehouseRows"></tbody></table></div>`;const draw=()=>{const q=text(document.getElementById('warehouseSearch').value).toLowerCase();const rows=state.data.receipts.filter(x=>!q||JSON.stringify(x).toLowerCase().includes(q));document.getElementById('warehouseRows').innerHTML=rows.map(x=>{const md=x.label_metadata||{};return `<tr><td class="mono"><b>${esc(x.gc_code_detected||x.gc_code||'—')}</b></td><td>${esc(x.location||'—')}</td><td class="mono">${esc(x.batch_code||'—')}</td><td>${number(x.carton_count||md.total_packages||1)}</td><td class="mono">${esc(x.scan_code||md.tracking_number||'—')}</td><td>${esc(x.created_by_name||'—')}</td><td>${number(Array.isArray(x.photos)?x.photos.length:0)}</td><td>${esc(date(x.received_at||x.created_at))}</td><td><button class="btn" data-receipt="${esc(x.id)}">بینین</button></td></tr>`}).join('')||`<tr><td colspan="9"><div class="empty">هیچ receipt نییە.</div></td></tr>`;document.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>receiptDetail(b.dataset.receipt));};document.getElementById('warehouseSearch').oninput=draw;draw();document.getElementById('newReceipt').onclick=newReceiptModal;document.getElementById('scanReceipt').onclick=()=>scannerModal('warehouse');}
  function receiptDetail(id){const r=state.data.receipts.find(x=>String(x.id)===String(id));if(!r)return;const photos=(r.photos||[]).map(u=>`<a class="photo" href="${esc(u)}" target="_blank" rel="noopener"><img src="${esc(u)}" alt="evidence"></a>`).join('');openModal(`Receipt · ${r.gc_code_detected||r.gc_code||''}`,`<div class="two-col"><section class="card"><h3>وەرگرتن</h3><p>کۆگا: <b>${esc(r.location)}</b></p><p>Batch: <span class="mono">${esc(r.batch_code)}</span></p><p>Cartons: <b>${esc(r.carton_count||1)}</b></p><p>Tracking: <span class="mono">${esc(r.scan_code||'—')}</span></p><p>کەسی وەرگر: ${esc(r.created_by_name||'—')}</p><p>${esc(date(r.received_at||r.created_at))}</p></section><section class="card"><h3>AI / Scan</h3><p>Verification: <span class="pill mint">${esc(r.verification_status||'—')}</span></p><p>OCR: ${esc(r.ocr_confidence??'—')}</p><p class="muted">${esc(r.ocr_text||'OCR بەردەست نییە')}</p></section><section class="card" style="grid-column:1/-1"><h3>Photos</h3><div class="photo-grid">${photos||'<div class="empty">وێنە نییە.</div>'}</div></section></div>`,'<button class="btn" data-close>داخستن</button>');}
  function newReceiptModal(prefill={}){openModal('وەرگرتنی کاڵا لە کۆگا',`<form id="receiptForm" class="form-grid" enctype="multipart/form-data"><div class="form-field"><label>GC code</label><input class="field" name="customer_code" required value="${esc(prefill.code||'')}" placeholder="GC-1005"></div><div class="form-field"><label>کۆگا</label><select class="field" name="location"><option>China</option><option>Dubai</option><option>Erbil</option><option>USA</option></select></div><div class="form-field"><label>Batch</label><input class="field" name="batch_code" value="${esc(prefill.batch||'')}"></div><div class="form-field"><label>Tracking</label><input class="field" name="tracking_number"></div><div class="form-field"><label>Cartons</label><input class="field" name="total_packages" type="number" min="1" value="1"></div><div class="form-field"><label>Gross kg</label><input class="field" name="gross_weight_kg" type="number" step="0.01"></div><div class="form-field"><label>Declared value</label><input class="field" name="declared_value" type="number" step="0.01"></div><div class="form-field"><label>Currency</label><select class="field" name="declared_currency"><option>USD</option><option>IQD</option></select></div><div class="form-field full"><label>کالاکان</label><textarea class="field" name="item_summary" placeholder="2 laptop, 5 cover"></textarea></div><div class="form-field full"><label>وێنەکان (تا 8)</label><input class="field" name="photos" type="file" accept="image/*" multiple capture="environment"></div><div class="form-field"><label>Latitude (optional)</label><input class="field" name="latitude" type="number" step="any"></div><div class="form-field"><label>Longitude (optional)</label><input class="field" name="longitude" type="number" step="any"></div></form>`,'<button class="btn" data-close>هەڵوەشاندنەوە</button><button class="btn primary" id="saveReceipt">تۆمارکردن</button>');document.querySelector('#receiptForm select[name=location]').value=prefill.location||'Dubai';document.getElementById('saveReceipt').onclick=async()=>{const form=document.getElementById('receiptForm');const fd=new FormData(form);fd.append('idempotency_key',crypto.randomUUID());fd.append('scan_type','qr');try{const r=await request(FN.warehouse,'/',{method:'POST',body:fd});closeModal();toast(`وەرگرتنی ${r.customer?.code||''} سەرکەوتوو بوو`);if(r.whatsapp_message)toast('پەیامی WhatsApp بۆ queue دانرا');await renderWarehouses()}catch(e){toast(e.message,'bad')}};}

  async function renderFinance(){const r=await ops('finance');state.data.finance=r;const tx=r.transactions||[];const income=tx.filter(x=>['income','customer_payment','payment'].includes(String(x.type))).reduce((s,x)=>s+Number(x.amount_usd||0),0),expense=tx.filter(x=>['expense','cost'].includes(String(x.type))).reduce((s,x)=>s+Number(x.amount_usd||0),0),charges=tx.filter(x=>['charge','customer_charge'].includes(String(x.type))).reduce((s,x)=>s+Number(x.amount_usd||0),0);document.getElementById('view').innerHTML=`<div class="section-head"><div><div class="eyebrow">FINANCE CONTROL</div><h1>دارایی</h1><p>داهات، خەرجی، قەرز و payment ـەکان لە یەک ledger.</p></div><button class="btn primary" id="newFinance">+ تۆمارکردنی پارە</button></div><div class="grid-kpi"><div class="kpi"><span>داهات</span><strong>${money(income)}</strong></div><div class="kpi"><span>خەرجی</span><strong>${money(expense)}</strong></div><div class="kpi"><span>قازانج</span><strong>${money(income-expense)}</strong></div><div class="kpi"><span>Charge</span><strong>${money(charges)}</strong></div><div class="kpi"><span>Transactions</span><strong>${number(tx.length)}</strong></div><div class="kpi"><span>قازانجی ڕێگا</span><strong>${money((state.data.shipments||[]).reduce((s,x)=>s+Number(x.total_amount||0),0))}</strong></div></div><div class="toolbar"><input class="field" id="financeSearch" placeholder="گەڕان بە GC / جۆر / reference"></div><div class="table-wrap"><table class="table"><thead><tr><th>بەروار</th><th>جۆر</th><th>GC</th><th>بڕ</th><th>Reference</th><th>Note</th><th></th></tr></thead><tbody id="financeRows"></tbody></table></div>`;const draw=()=>{const q=text(document.getElementById('financeSearch').value).toLowerCase();const rows=tx.filter(x=>!q||JSON.stringify(x).toLowerCase().includes(q));document.getElementById('financeRows').innerHTML=rows.slice(0,300).map(x=>`<tr><td>${esc(date(x.created_at||x.occurred_at))}</td><td><span class="pill ${String(x.type).includes('expense')?'red':'mint'}">${esc(x.type||'—')}</span></td><td class="mono">${esc(x.gc_code||'—')}</td><td class="mono"><b>${money(x.amount_usd||0)}</b></td><td>${esc(x.reference||x.provider_reference||'—')}</td><td>${esc(x.note||'')}</td><td><button class="btn" data-fin-edit="${esc(x.id)}">Edit</button></td></tr>`).join('')||`<tr><td colspan="7"><div class="empty">هیچ transaction ـێک نییە.</div></td></tr>`;document.querySelectorAll('[data-fin-edit]').forEach(b=>b.onclick=()=>editFinance(b.dataset.finEdit));};document.getElementById('financeSearch').oninput=draw;draw();document.getElementById('newFinance').onclick=newFinanceModal;}
  function newFinanceModal(){openModal('تۆمارکردنی مامەڵەی دارایی',`<form id="financeForm" class="form-grid"><div class="form-field"><label>Type</label><select class="field" name="type"><option>income</option><option>expense</option><option>customer_payment</option><option>customer_charge</option><option>refund</option><option>adjustment</option></select></div><div class="form-field"><label>USD amount</label><input class="field" name="amount_usd" type="number" step="0.01" min="0" required></div><div class="form-field"><label>GC</label><input class="field" name="gc_code" placeholder="GC-1005"></div><div class="form-field"><label>Reference</label><input class="field" name="reference"></div><div class="form-field full"><label>Note</label><textarea class="field" name="note"></textarea></div></form>`,'<button class="btn" data-close>هەڵوەشاندنەوە</button><button class="btn primary" id="saveFinance">پاشەکەوت</button>');document.getElementById('saveFinance').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('financeForm')).entries());try{await hubPost('finance_create',d);closeModal();toast('مامەڵەکە تۆمار کرا');await renderFinance()}catch(e){toast(e.message,'bad')}};}
  function editFinance(id){const x=(state.data.finance.transactions||[]).find(r=>String(r.id)===String(id));if(!x)return;openModal('دەستکاری transaction',`<form id="editFinance" class="form-grid"><input type="hidden" name="id" value="${esc(x.id)}"><div class="form-field"><label>Type</label><input class="field" name="type" value="${esc(x.type||'income')}"></div><div class="form-field"><label>USD</label><input class="field" name="amount_usd" type="number" step="0.01" value="${esc(x.amount_usd||0)}"></div><div class="form-field"><label>GC</label><input class="field" name="gc_code" value="${esc(x.gc_code||'')}"></div></form>`,'<button class="btn" data-close>داخستن</button><button class="btn primary" id="saveFinanceEdit">پاشەکەوت</button>');document.getElementById('saveFinanceEdit').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('editFinance')).entries());try{await hubPost('finance_update',d);closeModal();toast('نوێکرایەوە');await renderFinance()}catch(e){toast(e.message,'bad')}};}

  async function renderStaffChat(){const r=await account('chat');state.data.staffChat=r;state.data.chatRooms=r.rooms||[];if(!state.activeStaffRoom)state.activeStaffRoom=state.data.chatRooms[0]?.id;document.getElementById('view').innerHTML=`<div class="section-head"><div><div class="eyebrow">INTERNAL TEAM MESSAGING</div><h1>چاتی ستاف</h1><p>گفتوگۆی ناوخۆیی لە نێوان کارمەندان.</p></div></div><div class="chat-layout"><div class="room-list" id="staffRooms"></div><section class="chat-box"><div class="chat-head"><b id="staffChatTitle"></b><span id="staffChatDesc"></span></div><div class="messages" id="staffMessages"></div><form id="staffChatForm" class="composer"><input class="field" id="staffMessage" maxlength="4000" placeholder="پەیام بنووسە…"><button class="btn primary" type="submit">ناردن</button></form></section></div>`;drawStaffChat();document.getElementById('staffChatForm').onsubmit=async e=>{e.preventDefault();const body=text(document.getElementById('staffMessage').value);if(!body||!state.activeStaffRoom)return;try{await account('chat','send',{room_id:state.activeStaffRoom,body,client_message_id:crypto.randomUUID()});document.getElementById('staffMessage').value='';await renderStaffChat()}catch(err){toast(err.message,'bad')}};}
  function drawStaffChat(){const rooms=state.data.chatRooms||[];document.getElementById('staffRooms').innerHTML=rooms.map(r=>`<button class="room ${String(r.id)===String(state.activeStaffRoom)?'active':''}" data-staff-room="${esc(r.id)}"><b>${esc(r.name)}</b><span>${esc(r.description||'')}</span><em>${r.unread_count||0}</em></button>`).join('')||'<div class="empty">هێشتا room ـێک نییە.</div>';document.querySelectorAll('[data-staff-room]').forEach(b=>b.onclick=()=>{state.activeStaffRoom=b.dataset.staffRoom;drawStaffChat()});const room=rooms.find(r=>String(r.id)===String(state.activeStaffRoom));document.getElementById('staffChatTitle').textContent=room?.name||'Staff Room';document.getElementById('staffChatDesc').textContent=room?.description||'';document.getElementById('staffMessages').innerHTML=(room?.messages||[]).map(m=>`<article class="bubble ${String(m.sender_id)===String(state.staff.id)?'own':''}"><strong>${esc(String(m.sender_id)===String(state.staff.id)?'تۆ':m.sender?.full_name||'Staff')}</strong><p>${esc(m.body)}</p><time>${esc(date(m.created_at))}</time></article>`).join('')||'<div class="empty">یەکەم پەیامت بنێرە.</div>';const sc=document.getElementById('staffMessages');sc.scrollTop=sc.scrollHeight;}

  async function renderCustomerChat(){const r=await ops('chat');state.data.customerChat=r;const threads=r.threads||[];if(!state.activeCustomerThread)state.activeCustomerThread=threads[0]?.id;document.getElementById('view').innerHTML=`<div class="section-head"><div><div class="eyebrow">CUSTOMER SUPPORT</div><h1>چاتی کڕیار</h1><p>پرسیارەکانی کڕیاران، وەڵام و GC-linked conversations.</p></div></div><div class="chat-layout"><div class="room-list" id="customerRooms"></div><section class="chat-box"><div class="chat-head"><b id="customerChatTitle"></b><span id="customerChatDesc"></span></div><div class="messages" id="customerMessages"></div><form id="customerChatForm" class="composer"><input class="field" id="customerMessage" maxlength="4000" placeholder="وەڵام بنووسە…"><button class="btn primary" type="submit">ناردن</button></form></section></div>`;drawCustomerChat();document.getElementById('customerChatForm').onsubmit=async e=>{e.preventDefault();const body=text(document.getElementById('customerMessage').value);const th=threads.find(t=>String(t.id)===String(state.activeCustomerThread));if(!body||!th)return;try{await opsPost('chat_send',{thread_id:th.id,body,gc_code:th.gc_code,customer_user_id:th.customer_user_id});document.getElementById('customerMessage').value='';await renderCustomerChat()}catch(err){toast(err.message,'bad')}};}
  function drawCustomerChat(){const r=state.data.customerChat||{};const threads=r.threads||[];const msgs=r.messages||[];document.getElementById('customerRooms').innerHTML=threads.map(t=>`<button class="room ${String(t.id)===String(state.activeCustomerThread)?'active':''}" data-thread="${esc(t.id)}"><b>${esc(t.gc_code||'GC')}</b><span>${esc(t.subject||'Support')} · ${esc(t.status||'open')}</span><em>${esc(shortDate(t.last_message_at))}</em></button>`).join('')||'<div class="empty">هیچ customer chat ـێک نییە.</div>';document.querySelectorAll('[data-thread]').forEach(b=>b.onclick=()=>{state.activeCustomerThread=b.dataset.thread;drawCustomerChat()});const t=threads.find(x=>String(x.id)===String(state.activeCustomerThread));document.getElementById('customerChatTitle').textContent=t?`${t.gc_code||'GC'} · ${t.subject||'Support'}`:'Customer chat';document.getElementById('customerChatDesc').textContent=t?'کڕیار: '+(t.customer_user_id||'unknown'):'';document.getElementById('customerMessages').innerHTML=msgs.filter(m=>!t||String(m.thread_id)===String(t.id)).map(m=>`<article class="bubble ${String(m.sender_user_id)===String(state.staff.id)?'own':''}"><strong>${esc(m.sender_type||'customer')}</strong><p>${esc(m.body)}</p><time>${esc(date(m.created_at))}</time></article>`).join('')||'<div class="empty">هیچ پەیامێک نییە.</div>';}

  async function renderRequests(){const r=await account('quote_requests');state.data.quoteRequests=r.items||[];document.getElementById('view').innerHTML=`<div class="section-head"><div><div class="eyebrow">INBOX · REQUESTS</div><h1>ئاگاداری / داواکاری</h1><p>پرسیاری نرخ، داوای account و داواکارییەکانی کڕیار.</p></div></div><div class="list">${state.data.quoteRequests.length?state.data.quoteRequests.map(q=>`<article class="notice"><div><b>${esc(q.customer_name||'کڕیاری بێناو')}</b><p>${esc(kindLabel(q.kind||q.type))} · ${esc(q.customer_phone||q.customer_email||'')}</p><p>${esc(q.origin_key||'—')} → ${esc(q.dest_key||'—')} · ${esc(q.transport_mode||'—')} · ${esc(q.weight_kg??'—')} kg</p><small>${esc(date(q.created_at))}</small></div><div class="actions"><button class="btn" data-request-chat="${esc(q.id)}">Chat</button><button class="btn primary" data-request-account="${esc(q.id)}">دروستکردنی account</button></div></article>`).join(''):'<div class="empty">هیچ داواکارییەکی نوێ نییە.</div>'}</div>`;document.querySelectorAll('[data-request-account]').forEach(b=>b.onclick=()=>{const q=state.data.quoteRequests.find(x=>String(x.id)===String(b.dataset.requestAccount));newCustomerModal();if(q){setTimeout(()=>{const f=document.getElementById('customerForm');if(f){f.name.value=q.customer_name||'';f.phone.value=q.customer_phone||'';f.email.value=q.customer_email||''}},30)}});document.querySelectorAll('[data-request-chat]').forEach(b=>b.onclick=()=>loadTab('customer-chat'));}

  async function renderActivity(){const r=await account('log');state.data.logs=r.items||[];document.getElementById('view').innerHTML=`<div class="section-head"><div><div class="eyebrow">IMMUTABLE OPERATIONS TRACE</div><h1>Audit Log</h1><p>کێ چی کرد و لە کام entity ـەدا.</p></div></div><div class="toolbar"><input class="field" id="auditSearch" placeholder="گەڕان بە actor / action / target"></div><div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Target</th><th>Details</th></tr></thead><tbody id="auditRows"></tbody></table></div>`;const draw=()=>{const q=text(document.getElementById('auditSearch').value).toLowerCase();const rows=state.data.logs.filter(x=>!q||JSON.stringify(x).toLowerCase().includes(q));document.getElementById('auditRows').innerHTML=rows.map(x=>`<tr><td>${esc(date(x.created_at))}</td><td>${esc(x.staff_name||'—')}</td><td><span class="pill">${esc(x.action)}</span></td><td class="mono">${esc(x.target_id||'—')}</td><td>${esc(typeof x.details==='string'?x.details:JSON.stringify(x.details||''))}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">هیچ audit record ـێک نییە.</div></td></tr>'};document.getElementById('auditSearch').oninput=draw;draw();}

  async function renderSettings(){const r=await request(FN.hub,'/?kind=profile');const p=r.profile||{};document.getElementById('view').innerHTML=`<div class="section-head"><div><div class="eyebrow">PROFILE · SECURITY</div><h1>ڕێکخستنەکان</h1><p>زمان، ناو، پەیوەندی و وشەی نهێنی.</p></div></div><div class="two-col"><section class="card"><div class="card-head"><h3>Profile</h3><span class="pill">${esc(roleLabel(state.staff.role))}</span></div><form id="profileForm" class="form-grid"><div class="form-field"><label>ناوی تەواو</label><input class="field" name="full_name" value="${esc(state.staff.full_name||'')}"></div><div class="form-field"><label>Phone</label><input class="field" name="phone" value="${esc(p.settings?.phone||'')}"></div><div class="form-field"><label>Job title</label><input class="field" name="job_title" value="${esc(p.settings?.job_title||'')}"></div><div class="form-field"><label>Language</label><select class="field" name="locale"><option value="ckb" ${p.settings?.locale!=='en'?'selected':''}>کوردی</option><option value="en" ${p.settings?.locale==='en'?'selected':''}>English</option></select></div><div class="form-field full"><label>Timezone</label><input class="field" name="timezone" value="${esc(p.settings?.timezone||'Asia/Baghdad')}"></div></form><button class="btn primary" id="saveProfile" style="margin-top:9px">پاشەکەوت</button></section><section class="card"><div class="card-head"><h3>گۆڕینی وشەی نهێنی</h3><span class="pill warn">Self-service</span></div><form id="passwordForm" class="form-grid"><div class="form-field"><label>وشەی نوێ</label><input class="field" name="password" type="password" minlength="10" required></div><div class="form-field"><label>دووبارە</label><input class="field" name="confirm" type="password" minlength="10" required></div></form><button class="btn primary" id="savePassword" style="margin-top:9px">گۆڕین</button><div style="margin-top:12px;color:var(--muted);font-size:10px;line-height:1.8">2FA، RLS و Edge Function ـەکان بۆ role ـەکەی تۆ جێبەجێ دەکرێن.</div></section></div><section class="card" style="margin-top:10px"><div class="card-head"><h3>Staff & Roles</h3><span class="pill">${state.staff.role==='super_admin'?'Full control':'read / restricted'}</span></div><div class="actions"><button class="btn" id="openStaffManager">کردنەوەی Staff Manager</button></div></section>`;document.getElementById('saveProfile').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('profileForm')).entries());try{await hubPost('profile_update',d);state.staff.full_name=d.full_name;toast('Profile نوێکرایەوە')}catch(e){toast(e.message,'bad')}};document.getElementById('savePassword').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('passwordForm')).entries());if(d.password!==d.confirm)return toast('دوو وشەی نهێنی یەکسان نیین','bad');try{const r=await state.client.auth.updateUser({password:d.password});if(r.error)throw r.error;toast('وشەی نهێنی گۆڕدرا')}catch(e){toast(e.message,'bad')}};document.getElementById('openStaffManager').onclick=staffManager;}

  async function staffManager(){if(state.staff.role!=='super_admin')return toast('تەنها Super Admin دەتوانێت Staff بەڕێوەببات','bad');const r=await account('staff');state.data.staff=r.items||[];openModal('Staff Manager',`<div class="actions" style="margin-bottom:10px"><button class="btn primary" id="newStaffBtn">+ Staff</button><input class="field" id="staffQ" placeholder="گەڕان بە ناو / role / branch"></div><div class="table-wrap"><table class="table"><thead><tr><th>ناو</th><th>Role</th><th>Branch</th><th>Status</th><th></th></tr></thead><tbody id="staffRows"></tbody></table></div>`,'<button class="btn" data-close>داخستن</button>');const draw=()=>{const q=text(document.getElementById('staffQ').value).toLowerCase();const rows=state.data.staff.filter(x=>!q||`${x.full_name} ${x.role} ${x.branch}`.toLowerCase().includes(q));document.getElementById('staffRows').innerHTML=rows.map(x=>`<tr><td>${esc(x.full_name||'—')}</td><td>${esc(roleLabel(x.role))}</td><td>${esc(x.branch||'all')}</td><td><span class="pill ${x.is_active?'mint':'red'}">${x.is_active?'ACTIVE':'INACTIVE'}</span></td><td><button class="btn" data-staff-edit="${esc(x.id)}">Edit</button></td></tr>`).join('')};document.getElementById('staffQ').oninput=draw;draw();document.getElementById('newStaffBtn').onclick=newStaffModal;document.querySelectorAll('[data-staff-edit]').forEach(b=>b.onclick=()=>editStaff(b.dataset.staffEdit));}
  function newStaffModal(){openModal('دروستکردنی Staff',`<form id="staffForm" class="form-grid"><div class="form-field"><label>ناو</label><input class="field" name="full_name" required></div><div class="form-field"><label>Email</label><input class="field" name="email" type="email" required></div><div class="form-field"><label>Role</label><select class="field" name="role">${ROLES.map(r=>`<option value="${r}">${roleLabel(r)}</option>`).join('')}</select></div><div class="form-field"><label>Branch</label><select class="field" name="branch">${BRANCHES.map(b=>`<option>${b}</option>`).join('')}</select></div><div class="form-field"><label>Password</label><input class="field" name="password" type="text"></div><div class="form-field"><label>Invite</label><select class="field" name="send_invite"><option value="false">Create now</option><option value="true">Email invite</option></select></div></form>`,'<button class="btn" data-close>هەڵوەشاندنەوە</button><button class="btn primary" id="saveStaff">دروستکردن</button>');document.getElementById('saveStaff').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('staffForm')).entries());d.send_invite=d.send_invite==='true';try{const r=await account('staff','create',d);closeModal();toast(`${r.staff?.full_name||''} دروست کرا`);if(r.status==='created'&&d.password)toast(`Password: ${d.password}`)}catch(e){toast(e.message,'bad')}};}
  function editStaff(id){const x=state.data.staff.find(r=>String(r.id)===String(id));if(!x)return;openModal(`دەستکاری Staff · ${x.full_name||''}`,`<form id="editStaff" class="form-grid"><input type="hidden" name="id" value="${esc(x.id)}"><div class="form-field"><label>ناو</label><input class="field" name="full_name" value="${esc(x.full_name||'')}"></div><div class="form-field"><label>Role</label><select class="field" name="role">${ROLES.map(r=>`<option value="${r}" ${r===x.role?'selected':''}>${roleLabel(r)}</option>`).join('')}</select></div><div class="form-field"><label>Branch</label><select class="field" name="branch">${BRANCHES.map(b=>`<option ${b===x.branch?'selected':''}>${b}</option>`).join('')}</select></div><div class="form-field"><label>Active</label><select class="field" name="is_active"><option value="true" ${x.is_active?'selected':''}>Active</option><option value="false" ${!x.is_active?'selected':''}>Inactive</option></select></div><div class="form-field full"><label>New password</label><input class="field" name="password" type="text"></div></form>`,'<button class="btn" data-close>داخستن</button><button class="btn primary" id="saveEditStaff">پاشەکەوت</button>');document.getElementById('saveEditStaff').onclick=async()=>{const d=Object.fromEntries(new FormData(document.getElementById('editStaff')).entries());d.is_active=d.is_active==='true';try{await account('staff','update',d);toast('Staff نوێکرایەوە');closeModal();await staffManager()}catch(e){toast(e.message,'bad')}};}

  function updateBadges(){const set=(id,n)=>{const x=document.getElementById(id);if(!x)return;x.textContent=String(n||0);x.classList.toggle('hidden',!n)};const alerts=(state.data.alerts||[]).filter(x=>!Array.isArray(x.read_by)||!x.read_by.includes(state.staff?.id)).length;const requests=(state.data.quoteRequests||[]).filter(x=>!['closed','replied','accepted','rejected'].includes(x.status)).length;const staffChat=(state.data.chatRooms||[]).reduce((s,x)=>s+Number(x.unread_count||0),0);set('alertsBadge',alerts);set('requestBadge',requests);set('staffChatBadge',staffChat);set('customerChatBadge',(state.data.customerChat?.threads||[]).filter(x=>x.status==='open').length);}

  function openModal(title, body, footer='') { closeModal(); const back=document.createElement('div'); back.className='modal-backdrop'; back.id='gcModal'; back.innerHTML=`<div class="modal"><div class="modal-head"><div><div class="eyebrow">GLOBAL CLOUD · CONTROL</div><h2>${esc(title)}</h2></div><button class="btn" data-close>×</button></div><div>${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</div>`;document.body.appendChild(back);back.addEventListener('click',e=>{if(e.target===back||e.target.closest('[data-close]'))closeModal()});return back; }
  function closeModal(){document.getElementById('gcModal')?.remove();stopScanner();}

  async function scannerModal(kind){
    openModal(kind==='customer'?'Scan GC Customer':'Scan GC for Warehouse',`<div class="scanner"><video id="scanVideo" autoplay playsinline muted></video><div class="scanline"></div></div><div id="scanStatus" class="muted" style="margin-top:9px">Camera دەستپێدەکات…</div>`,'<button class="btn" id="manualScan">دابینکردنی دستی</button><button class="btn" data-close>داخستن</button>');
    try { state.scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const v=document.getElementById('scanVideo');v.srcObject=state.scanStream; await v.play(); if('BarcodeDetector' in window){const detector=new BarcodeDetector({formats:['qr_code','code_128','ean_13','code_39']});const tick=async()=>{if(!state.scanStream)return;try{const found=await detector.detect(v);if(found?.length){const raw=text(found[0].rawValue).toUpperCase().replace(/\s+/g,'');const code=(raw.match(/GC-[A-Z0-9-]{2,30}/)||[])[0]||raw;stopScanner();closeModal(); if(kind==='customer'){const c=state.data.customers.find(x=>String(x.gc_code||x.code).toUpperCase()===code); if(c)customerDetail(c.id); else toast(`کۆدی ${code} نەدۆزرایەوە`,'bad')}else newReceiptModal({code});return;}}catch{}requestAnimationFrame(tick)};requestAnimationFrame(tick)}else document.getElementById('scanStatus').textContent='Browser ـەکەت BarcodeDetector پشتگیری ناکات؛ دابینکردنی دستی بەکاربهێنە.';}catch(e){document.getElementById('scanStatus').textContent=`Camera بەردەست نییە: ${e.message}`;}
    document.getElementById('manualScan').onclick=()=>{const code=prompt('GC code بنووسە');closeModal();if(code){if(kind==='customer'){const c=state.data.customers.find(x=>String(x.gc_code||x.code).toUpperCase()===code.toUpperCase());c?customerDetail(c.id):toast('GC نەدۆزرایەوە','bad')}else newReceiptModal({code:code.toUpperCase()});}};
  }
  function stopScanner(){if(state.scanStream){state.scanStream.getTracks().forEach(t=>t.stop());state.scanStream=null;}}

  window.addEventListener('beforeunload',stopScanner);

  async function boot(){
    try { await waitForSupabase(); const ready=await verifyStoredSession(); if(!ready) renderLogin(false); }
    catch(e){ renderLogin(false,e.message); }
  }
  boot();
})();
